// Original modern illustrations: fictional parcel and a non-metric place schematic.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function archiveParcelArt(){return `<svg class="ta-parcel-art" viewBox="0 0 540 205" role="img" aria-label="Original illustration of a fictional present-day parcel containing a photograph and date cards. This is not a historical artifact."><path d="M45 46 465 20l40 133-421 31Z" fill="#d5bc88" stroke="#735745" stroke-width="2"/><path d="m45 46 229 59 191-85M84 184l190-79 231 48" fill="none" stroke="#9a7d50" stroke-width="2"/><path d="m214 34 23 141M61 111l427-26" fill="none" stroke="#fffef9" stroke-width="5"/><g transform="rotate(-5 295 86)"><rect x="265" y="47" width="189" height="85" rx="3" fill="#fffef9" stroke="#b9c8cf"/><text x="284" y="79" fill="#183f39" font-family="Georgia,serif" font-size="24">Paris, 1910</text><text x="284" y="108" fill="#526b7f" font-size="16">A picture. A question.</text></g><circle cx="128" cy="101" r="26" fill="#526b7f"/><path d="M115 101h26m-13-13v26" stroke="#fffef9" stroke-width="3"/><text x="270" y="200" text-anchor="middle" fill="#526b7f" font-size="13">Fictional present-day parcel</text></svg>`;}
export function archivePlaceMap(selected=null){return `<figure class="ta-map"><svg viewBox="0 0 540 270" role="img" aria-label="Original modern schematic of two named places by the Seine in Paris. The photograph is labeled Quai des Grands-Augustins; the measuring-scale event names Pont d’Austerlitz. The outline and spacing are simplified, not to scale or a route."><rect x="1" y="1" width="538" height="268" rx="8" fill="#f0f5f5"/><path d="M-12 55C92 40 133 118 216 99S355 117 397 164 450 214 553 222" fill="none" stroke="#abc4da" stroke-width="40"/><path d="M-12 55C92 40 133 118 216 99S355 117 397 164 450 214 553 222" fill="none" stroke="#fffef9" stroke-width="2" stroke-dasharray="6 7"/><text x="295" y="62" font-family="Georgia,serif" font-size="22" fill="#526b7f">La Seine</text><g transform="translate(152 104)"><circle r="20" fill="${selected==='grands-augustins'?'#d6e7d3':'#fffef9'}" stroke="#183f39" stroke-width="2"/><path d="M-10-6h5l2-4h7l2 4h5v14h-21Z" fill="none" stroke="#183f39" stroke-width="2"/><circle cx="0" cy="1" r="4" fill="none" stroke="#183f39" stroke-width="2"/></g><path d="M151 125v27" stroke="#735745"/><text x="30" y="177" font-size="18" fill="#183f39">Quai des Grands-Augustins</text><text x="30" y="200" font-size="15" fill="#526b7f">Photo location</text><g transform="translate(399 155)"><circle r="20" fill="${selected==='austerlitz'?'#d6e7d3':'#fffef9'}" stroke="#183f39" stroke-width="2"/><path d="M-5-12v24h12M-5-8h6m-6 7h9m-9 7h6" fill="none" stroke="#183f39" stroke-width="2"/></g><path d="M399 134v-30" stroke="#735745"/><text x="348" y="80" font-size="18" fill="#183f39">Pont d’Austerlitz</text><text x="348" y="101" font-size="14" fill="#526b7f">Gauge location</text><text x="270" y="253" text-anchor="middle" font-size="13" fill="#526b7f">Modern schematic · not to scale · not a route</text></svg><figcaption>Camera: photograph’s named place. Measuring scale: highest-mark event’s named place.</figcaption></figure>`;}
export function archiveDateCard(event){return `<span class="ta-date-card"><strong>${esc(event.dateLabel)}</strong><span>${esc(event.title)}</span></span>`;}
